export default function Stepper({ steps, current }) {
  return (
    <div className="flex items-center justify-center mb-10">
      {steps.map((label, i) => {
        const num   = i + 1;
        const done  = num < current;
        const active = num === current;

        return (
          <div key={label} className="flex items-center">
            {/* Line before */}
            {i > 0 && (
              <div className={`w-20 h-px mx-1 ${done ? "bg-red" : "bg-gray-200"}`} />
            )}

            <div className="flex items-center gap-2">
              <div
                className={`w-9 h-9 rounded-full flex items-center justify-center text-sm font-medium border transition-all
                  ${done  ? "bg-red border-red text-white"          : ""}
                  ${active ? "border-red text-red font-semibold bg-white" : ""}
                  ${!done && !active ? "border-gray-200 text-gray-400 bg-white" : ""}
                `}
              >
                {done ? "✓" : num}
              </div>
              <span className={`text-xs ${active ? "text-red font-medium" : "text-gray-400"}`}>
                {label}
              </span>
            </div>
          </div>
        );
      })}
    </div>
  );
}
